function validatePerformance(text,model,emotion){if(/^eleven_/.test(model)){if(model==='eleven_v3'&&text.length>5000)throw Error('Eleven v3 单次最多 5000 字，请拆分台词。');return;}if(/^s[12]/.test(model))return;if(!emotions.some(x=>x[0]===(emotion||'')))throw Error('语气选项无效，请重新选择。');if(['fluent','whisper'].includes(emotion)&&!/^speech-2\.6-(hd|turbo)$/.test(model))throw Error('生动、低语语气需使用 speech-2.6-hd 或 speech-2.6-turbo。');const tagPattern=new RegExp('\\(('+speechTags.map(x=>x[0]).join('|')+')\\)','g');if(new RegExp(tagPattern.source).test(text)&&!/^speech-2\.8-(hd|turbo)$/.test(model))throw Error('文本中的语气词需要 speech-2.8 模型；请切换模型或删除语气词。');const pauses=[...text.matchAll(/<#([^<>]*?)#>/g)];if(text.replace(/<#([^<>]*?)#>/g,'').includes('<#'))throw Error('停顿标记不完整，请使用“插入停顿”。');if(!pauses.length)return;const pieces=text.split(/<#[^<>]*?#>/);const spoken=part=>/[\p{L}\p{N}]/u.test(part.replace(tagPattern,''));if(!pieces.every(spoken))throw Error('每个停顿都要放在可朗读的文字之间，不能放在开头、末尾或连续插入。');for(const match of pauses){const raw=match[1],value=Number(raw);if(!/^\d+(?:\.\d{1,2})?$/.test(raw)||value<.01||value>99.99)throw Error('停顿时长须为 0.01–99.99 秒，最多两位小数。');}}

