on($('batchMake'),'click',async()=>{if(pending||batchBusy||mixBusy||syncBusy||profilesBusy||translationPending)return status('请先完成当前任务。');let options,script;try{options=readMixOptions();script=batchDraft.map((row,i)=>batchEntry(row,i));}catch(e){return $('batchStatus').textContent=e.message;}batchBusy=true;stop();const token=++generation,ctrl=new AbortController();pending=ctrl;lockProfiles(true);$('speak').disabled=true;$('batchCancel').hidden=false;for(const el of batchBox.querySelectorAll('input,select,textarea,button'))if(el!==$('batchCancel'))el.disabled=true;const check=()=>{if(dead||token!==generation||ctrl.signal.aborted)throw Error('已停止，已生成片段已保留。');};try{const records=await historyList(),result=[];for(let i=0;i<script.length;i++){check();const entry=script[i],{config:c,key,signature}=entry;let record=records.find(r=>r.id===entry.draft.recordId&&entry.draft.signature===signature);if(!record){$('batchStatus').textContent='正在生成 '+(i+1)+' / '+script.length+' · '+(c.provider==='elevenlabs'?'ElevenLabs':c.provider==='fish'?'鱼声':'MiniMax')+' · '+entry.voice.name;const blob=await synthesizeVoice(c,entry.voice,entry.text,key,ctrl.signal);check();record=await saveRecording(blob,c,entry.voice,entry.text);entry.draft.recordId=record.id;entry.draft.signature=signature;saveBatchDraft();}result.push(record);}$('batchStatus').textContent='台词已生成，正在拼成完整对话…';postMixId='';const row=await saveVoiceMix(result,$('batchTitle').value.trim(),options,check,text=>$('batchStatus').textContent=text);check();tab('history');await renderHistory();await playHistory(row);$('batchStatus').textContent='完整对话已保存。';status('多角色对话已保存，可播放、下载、收藏或拆开。');}catch(e){$('batchStatus').textContent='未完成：'+(e?.message||e)+' 已生成片段保留，继续时会跳过未改动的片段。';}finally{batchBusy=false;if(pending===ctrl)pending=null;$('batchCancel').hidden=true;$('speak').disabled=false;lockProfiles(false);for(const el of batchBox.querySelectorAll('input,select,textarea,button'))el.disabled=false;drawBatch();await loadInline();}});

