const storageTools=node('details');storageTools.innerHTML='<summary>分类、日期管理与打包下载</summary><label>分类<select data-id="historyKind"><option value="">全部成品与单段</option><option value="mix">大配音成品</option><option value="single">单段配音</option><option value="parts">大配音原片段</option></select></label><div class="lv-grid"><label>起始日期<input data-id="zipFrom" type="date"></label><label>结束日期（包含当天）<input data-id="zipTo" type="date"></label></div><label><input data-id="zipParts" type="checkbox">打包包含大配音原片段</label><button type="button" data-id="zipDownload">ZIP 打包下载</button><label>删除此日期之前的录音<input data-id="deleteBefore" type="date"></label><button type="button" data-id="deleteOld">预览批量删除</button><p data-id="storageStatus" role="status"></p>';$('historySearch').parentElement.before(storageTools);
