on($('deleteOld'),'click',async()=>{if(pending||batchBusy||mixBusy||syncBusy||profilesBusy)return status('请先完成当前任务。');try{const cutoff=dateBoundary($('deleteBefore').value),rows=await historyList(),old=new Set(rows.filter(r=>r.createdAt<cutoff).map(r=>r.id)),protectedIds=new Set(rows.filter(r=>!old.has(r.id)).flatMap(r=>r.mix?.parts||[])),ids=[...old].filter(id=>!protectedIds.has(id));if(!ids.length)return $('storageStatus').textContent='没有可删除的录音。';if(!W.confirm('删除 '+$('deleteBefore').value+' 之前的 '+ids.length+' 条录音？另有 '+[...old].filter(id=>protectedIds.has(id)).length+' 条被较新的大配音引用，会保留。'))return;clearInlineCache();stopHistory();stopInline();await historyTx(['records','audio'],'readwrite',tx=>{for(const id of ids){tx.objectStore('records').delete(id);tx.objectStore('audio').delete(id);}});ids.forEach(id=>recordPicks.delete(id));await loadInline();await renderHistory();$('storageStatus').textContent='已删除 '+ids.length+' 条本地录音。工作台中的独立收藏副本仍保留。';}catch(e){$('storageStatus').textContent=safe(e.message);}});
function crc32(bytes){let crc=0xffffffff;for(const b of bytes){crc^=b;for(let i=0;i<8;i++)crc=(crc>>>1)^((crc&1)?0xedb88320:0);}return (crc^0xffffffff)>>>0;}
async function zipAudio(rows){const parts=[],central=[];let offset=0,total=0;for(let i=0;i<rows.length;i++){const row=rows[i],data=new Uint8Array(await (await historyBlob(row.id)).arrayBuffer());total+=data.length;if(total>500*1024*1024)throw Error('打包音频超过 500 MB，请缩短日期范围。');const name=new TextEncoder().encode(String(i+1).padStart(4,'0')+'-'+recordingName(row));const crc=crc32(data),local=new Uint8Array(30),lv=new DataView(local.buffer);lv.setUint32(0,0x04034b50,true);lv.setUint16(4,20,true);lv.setUint16(6,0x800,true);lv.setUint32(14,crc,true);lv.setUint32(18,data.length,true);lv.setUint32(22,data.length,true);lv.setUint16(26,name.length,true);const header=new Uint8Array(46),cv=new DataView(header.buffer);cv.setUint32(0,0x02014b50,true);cv.setUint16(4,20,true);cv.setUint16(6,20,true);cv.setUint16(8,0x800,true);cv.setUint32(16,crc,true);cv.setUint32(20,data.length,true);cv.setUint32(24,data.length,true);cv.setUint16(28,name.length,true);cv.setUint32(42,offset,true);central.push(header,name);parts.push(local,name,data);offset+=local.length+name.length+data.length;$('storageStatus').textContent='打包 '+(i+1)+' / '+rows.length;await new Promise(r=>W.setTimeout(r,0));}const size=central.reduce((n,p)=>n+p.length,0),end=new Uint8Array(22),view=new DataView(end.buffer);view.setUint32(0,0x06054b50,true);view.setUint16(8,rows.length,true);view.setUint16(10,rows.length,true);view.setUint32(12,size,true);view.setUint32(16,offset,true);return new W.Blob([...parts,...central,end],{type:'application/zip'});}
